-- استيراد المخزون
begin;

do $$
declare v_11 uuid; v_ssr uuid; v_jz uuid;
begin
  select id into v_11 from pos_locations where name ilike '%11 يونيو%' limit 1;
  select id into v_ssr from pos_locations where name ilike '%السراج%' limit 1;
  select id into v_jz from pos_locations where name ilike '%جنزور%' limit 1;
  if v_11 is null or v_ssr is null or v_jz is null then
    raise exception 'لم يتم العثور على الفروع';
  end if;
end $$;
commit;
